"""Bind a completed normalized view to an actual independent row/source admission."""
import argparse,json,hashlib
from pathlib import Path
from classify_complete import admitted
HERE=Path(__file__).resolve().parent
BASE=HERE.parents[1]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--normalized',required=True);ap.add_argument('--admission',required=True);ap.add_argument('--output',required=True);a=ap.parse_args();d=Path(a.normalized).resolve();reviewp=Path(a.admission).resolve();out=Path(a.output)
 if out.exists():raise FileExistsError('Fresh contract path required')
 review=json.loads(reviewp.read_text());admitted(review);receipt=json.loads((d/'receipt.json').read_text());units=d/'normalized_units.parquet';nodes=d/'effective_population_source_view.parquet';assert review['units_sha256']==sha(units) and review.get('accepted_units_sha256',sha(units))==sha(units) and review['nodes_sha256']==sha(nodes)
 assert review['rural_excludes_exact_central_set'] is True and review['whole_members_counted_once'] is True
 for f,s in receipt['files'].items():assert sha(d/f)==s
 method=BASE/'reviews/cycle07_scale_typology_contract/complete_typology_prospective_code_admission.json';methodreview=json.loads(method.read_text());admitted(methodreview)
 assert methodreview['accepted_classifier_sha256']==sha(HERE/'classify_complete.py') and methodreview['accepted_protocol_sha256']==sha(HERE/'PROTOCOL.md')
 sourceoverlay=BASE/'demography2010_recovery_cycle06/admitted_overlay_v2_table5_adygea/full_axis_primary2010_overlay.parquet';overlayreview=BASE/'reviews/cycle07_primary2010_independent/overlay353_admission.json'
 context=json.loads((HERE/'context_projection_preregistration_v1.json').read_text())
 c={'status':'BOUND_ACTUAL_INDEPENDENTLY_RECONSTRUCTED_UNITS_FOR_COMPLETE_TYPING','units_path':str(units),'units_sha256':sha(units),'unit_id_column':'unit_id','unit_name_column':'name','kind_column':'kind','unit_role_column':'unit_role','level_column':'level','central_object_ids_column':'central_object_ids_json','central_object_definition_column':'central_object_definition','rural_member_count_column':'n_rural_external_settlements','unknown_role_member_count_column':'n_unknown_role_external_settlements','primary_annual_delta':.0025,'protocol_admission_path':str(method),'protocol_admission_sha256':sha(method),'central_set_audit_path':str(reviewp),'central_set_audit_sha256':sha(reviewp),'hierarchy_admission_path':str(reviewp),'hierarchy_admission_sha256':sha(reviewp),'objects':{},'quality_columns':['center_scope','population_quality_share_denominator_scope','primary2010_population_share','protected_secondary2010_population_share','population2010_known_denominator','2010_missing_population_count','unknown_nonadditive_central_population_slots2010','n_members_primary2010_newly_recovered','n_members_primary2010_numeric_changed','n_members_primary2010_quality_changed','primary2010_newly_recovered_population_share','prior_secondary2010_population_share','current_secondary2010_population_share','historical_boundary_equivalence_proven'],'quality_uncertainty_rules':[{'column':'classification_population_exact_primary_supported_2010','rule':'not_true','label':'recent2010_not_all_exact_primary_supported'},{'column':'classification_population_exact_primary_supported_2021','rule':'not_true','label':'recent2021_not_all_exact_primary_supported'},{'column':'historical_boundary_equivalence_proven','rule':'not_true','label':'historical_boundary_equivalence_unproven'}],'source_admissions':[],'population_source_version':{'mode':'admitted_versioned_overlay','base_nodes_sha256':receipt['base_nodes_sha256'],'effective_nodes_sha256':sha(nodes),'overlay_path':str(sourceoverlay),'overlay_sha256':sha(sourceoverlay),'admission_path':str(overlayreview),'admission_sha256':sha(overlayreview),'unit_quality_change_columns':['n_members_primary2010_newly_recovered','primary2010_newly_recovered_population_share','n_members_primary2010_numeric_changed','n_members_primary2010_quality_changed','prior_secondary2010_population_share','current_secondary2010_population_share']},'context_witnesses':[],'scientific_scope':'Complete measured partition in one actual operationalcap/forest view; empirical geographical levels/causal Word9 mechanisms not thereby established','normalized_receipt_path':str(d/'receipt.json'),'normalized_receipt_sha256':sha(d/'receipt.json')}
 for obj,prefix in [('own','own_population'),('center','center_population'),('rural','rural_external_population_known_sum'),('system','system_population_known_sum')]:
  c['objects'][obj]={'population':{str(y):f'{prefix}_{y}' for y in (2002,2010,2021)},'complete':{str(y):f'{obj}_population_complete_{y}' for y in (2002,2010,2021)}}
 for y in (2002,2010,2021):c['quality_columns'] += [f'population_quality_counts_json_{y}',f'center_population_quality_counts_json_{y}',f'classification_population_exact_primary_supported_{y}',f'classification_secondary_population_share_{y}']
 for y in (2002,2010,2021):
  c['quality_columns'] += [f'unknown_nonadditive_metropolitan_{role}_population_slots_{y}' for role in ('all','focal','nonfocal')]
 for x in context['context_projection']:c['context_witnesses'].append({'column':x['output_column'],'label':x['output_column'],'kind':'boolean','source':x['source'],'year':x['year'],'grain':x['grain'],'absence_is_unknown':True})
 for rp in (reviewp,method,overlayreview,BASE/'reviews/cycle07_baseline_units_independent/audit.json'):
  r=json.loads(rp.read_text());admitted(r);c['source_admissions'].append({'path':str(rp),'sha256':sha(rp),'required_fields':{'status':r['status'],'all_checks_passed':True}})
 out.parent.mkdir(parents=True,exist_ok=True);out.write_text(json.dumps(c,ensure_ascii=False,indent=2));print(json.dumps({'contract':str(out),'sha256':sha(out),'units_sha256':sha(units)}))
if __name__=='__main__':main()
